// on. `Ray` is the default so specs persisted before multi-engine — and any
// client that omits the field — still deserialize as Ray clusters, exactly
// as before.
type Engine string

// EnvironmentScan The recorded vulnerability-scan verdict for an environment (#52): an administrator records the outcome of the offline scan workflow (trivy/grype on the base image, pip-audit on the package list) here; the control plane does not scan itself.
type EnvironmentScan struct {
	// ScannedAt When the scan ran.
	ScannedAt *time.Time `json:"scanned_at,omitempty"`

	// Scanner What produced the verdict (e.g. "trivy 0.57.0", "pip-audit 2.7").
	Scanner *string `json:"scanner,omitempty"`

	// Status The verdict: clean | failed | pending.
	Status EnvironmentScanStatus `json:"status"`
}

// EnvironmentScanStatus The verdict: clean | failed | pending.
type EnvironmentScanStatus string

// EnvironmentSpec A named, governed compute environment in the environment catalog (#52): the base image, pinned packages and env vars a job or cluster gets when its spec names this environment (`RayJobSpec.environment`, `ClusterSpec.environment`). Environments compile to a governed runtime_env (#53); `runtime_env_yaml` is the documented escape hatch. Inert in #52: references are accepted and stored, resolution arrives with the catalog issue.
type EnvironmentSpec struct {
	// BaseImage Container image the environment builds on; admission image allowlists apply to it as to any spec image.
	BaseImage *string `json:"base_image,omitempty"`

	// Description Human-readable summary shown by clients.
	Description *string `json:"description,omitempty"`

	// EnvVars Environment variables every workload using this environment runs with; empty = none.
	EnvVars *map[string]string `json:"env_vars,omitempty"`

	// Name Catalog name a spec refers to (an RFC 1123 label, so it can ride Kubernetes object names).
	Name string `json:"name"`

	// Packages Pip requirements, each pinned to an exact version (`name[extras]==version`) — the same pin rule the runtime_env governance validator (#53) enforces. Empty = the base image alone.
	Packages *[]string `json:"packages,omitempty"`

	// Projects Projects that may use this environment; empty = every project.
	Projects *[]string `json:"projects,omitempty"`

	// PublishedAt When the environment was published; `null` while in draft.
	PublishedAt *time.Time `json:"published_at,omitempty"`

	// PublishedBy The identity that published the environment; `null` while in draft.
	PublishedBy *string `json:"published_by,omitempty"`

	// RuntimeEnvYaml Escape hatch: an extra Ray runtime_env YAML document merged in at resolution time, governed by the same validator (#53) a job's own runtime_env_yaml passes. Empty = none.
	RuntimeEnvYaml *string `json:"runtime_env_yaml,omitempty"`

	// Scan The scan verdict recorded for this environment; `null` = never scanned.
	Scan *EnvironmentScan `json:"scan,omitempty"`

	// Status Lifecycle state: a draft is editable and not yet selectable, published is selectable by specs, deprecated stays resolvable for existing references but should not be picked for new work. Absent = draft.
	Status *EnvironmentSpecStatus `json:"status,omitempty"`
}

// EnvironmentSpecStatus Lifecycle state: a draft is editable and not yet selectable, published is selectable by specs, deprecated stays resolvable for existing references but should not be picked for new work. Absent = draft.
type EnvironmentSpecStatus string

// FlavorSpec A hardware flavor within a pool: node selection plus per-resource
// nominal quota (K8s quantity strings, e.g. "4", "512Gi").
type FlavorSpec struct {
	Name       string            `json:"name"`
	NodeLabels map[string]string `json:"node_labels"`

	// Resources Resource key → nominal quota quantity string.
	Resources map[string]string `json:"resources"`
	Taints    []TaintSpec       `json:"taints"`
}

// GpuSharing How a pool's GPUs may be shared between workloads (#58).
//
// NVIDIA GPU time-slicing (and fractional `nvidia.com/gpu` requests via the
// device plugin) shares one GPU's SMs across processes with no hardware
// isolation — acceptable within one tenant, never across tenants. MIG is
// hardware partitioning and whole-GPU allocation needs no sharing at all,
// so both are isolation-safe. The tenant-isolation rule itself is enforced
// by the policy package's GPU admission logic at admission time; this field is the per-pool
// knob it evaluates.
type GpuSharing string

// IdentityResponse `GET /api/v1/identity` response: the caller's resolved identity.
type IdentityResponse struct {
	Email  *string  `json:"email,omitempty"`
	Groups []string `json:"groups"`

	// Projects The projects the caller holds scoped grants in, from group-derived
	// project roles and stored assignments alike, sorted by name.
	//
	// Distinct from `roles`, which lists the caller's *global* roles: a global
	// operator may act in every project and this list can name none, so a
	// client that finds it empty should read `roles` before concluding the
	// caller may do nothing.
	Projects []ProjectGrant `json:"projects"`

	// Roles Snake_case role names ("viewer", "developer", "operator", "admin").
	Roles   []string `json:"roles"`
	Subject string   `json:"subject"`
}

// JobView A job in the persistent, cross-cluster history (Phase 3, spec §5.5).
type JobView struct {
	Cluster string `json:"cluster"`

	// DurationSecs Wall-clock seconds once terminal; null while running.
	DurationSecs *int64 `json:"duration_secs,omitempty"`
	Id           string `json:"id"`

	// Status Ray job status (PENDING | RUNNING | SUCCEEDED | FAILED | STOPPED).
	Status      string `json:"status"`
	SubmittedAt int64  `json:"submitted_at"`
	Submitter   string `json:"submitter"`
}

// LocalRole A local user's role (ADR-0011: roles are a column on the user, resolved
// per request — no claim staleness). Stored as TEXT in `local_users.role`;
// the vocabulary mirrors the auth subsystem's Role type (kept as a separate enum so
// core never depends on the auth package).
type LocalRole string

// LocalUserView The public projection of a local user — everything EXCEPT the password
// hash and the lockout internals that are nobody else's business.
type LocalUserView struct {
	// CreatedAt Unix seconds.
	CreatedAt int64   `json:"created_at"`
	Disabled  bool    `json:"disabled"`
	Email     *string `json:"email,omitempty"`

	// Role A local user's role (ADR-0011: roles are a column on the user, resolved
	// per request — no claim staleness). Stored as TEXT in `local_users.role`;
	// the vocabulary mirrors the auth subsystem's Role type (kept as a separate enum so
	// core never depends on the auth package).
	Role     LocalRole `json:"role"`
	Username string    `json:"username"`
}

// LoginIdentity The identity half of a login response.
type LoginIdentity struct {
	Roles   []string `json:"roles"`
	Subject string   `json:"subject"`
}

// LoginRequest defines model for LoginRequest.
type LoginRequest struct {
	Password string `json:"password"`
	Username string `json:"username"`
}

// LoginResponse `POST /api/v1/auth/login` success body. `token` is an opaque
// `bfr_…` bearer credential (ADR-0011: stored, never signed).
type LoginResponse struct {
	// ExpiresAt Unix seconds after which the token no longer authenticates.
	ExpiresAt int64 `json:"expires_at"`

	// Identity The identity half of a login response.
	Identity LoginIdentity `json:"identity"`
	Token    string        `json:"token"`

	// TokenType Always "bearer".
	TokenType string `json:"token_type"`
}

// NodeView A single Ray node (head or one worker) as Kubernetes sees it: the pod
// KubeRay created for it, its scheduling/readiness, and the compute it
// requests. Fields are `Option` because a pod may not yet be scheduled
// (no IP/host) and a quantity may be unparseable or unset.
type NodeView struct {
	// Cpu CPU cores requested, summed across the pod's containers and parsed
	// from the K8s quantity (`500m` → 0.5). `None` when unset/unparseable.
	Cpu *float64 `json:"cpu,omitempty"`

	// Gpu GPUs requested (`nvidia.com/gpu`), summed across containers. `None`
	// when the pod requests no GPU.
	Gpu *float64 `json:"gpu,omitempty"`

	// Group Worker-group name (`ray.io/group`); `None` for the head node.
	Group *string `json:"group,omitempty"`

	// Host Kubernetes node the pod landed on (`spec.nodeName`); `None` before
	// scheduling.
	Host *string `json:"host,omitempty"`

	// IsHead Whether this is the cluster's head node.
	IsHead bool `json:"is_head"`

	// MemoryBytes Memory bytes requested, summed across the pod's containers (`2Gi` →
	// 2147483648). `None` when unset/unparseable.
	MemoryBytes *int64 `json:"memory_bytes,omitempty"`

	// NodeIp Pod IP once scheduled (`status.podIP`); `None` before scheduling.
	NodeIp *string `json:"node_ip,omitempty"`

	// Phase Kubernetes pod phase: `Pending` | `Running` | `Succeeded` | `Failed` |
	// `Unknown` (verbatim from `status.phase`).
	Phase string `json:"phase"`

	// PodName The pod's name (`metadata.name`).
	PodName string `json:"pod_name"`

	// Ready Whether the pod's `Ready` condition is true. Distinct from `phase`: a
	// pod can be `Running` but not yet `Ready`.
	Ready bool `json:"ready"`
}

// OidcProviderInfo defines model for OidcProviderInfo.
type OidcProviderInfo struct {
	Issuer string `json:"issuer"`
}

// PolicyView `GET /api/v1/settings/policy` response: the effective policy plus its
// provenance.
type PolicyView struct {
	// Admission project (or `"*"`) → admission limits (#7). Empty when none are configured.
	Admission *map[string]AdmissionRule `json:"admission,omitempty"`

	// Budgets project → time-windowed compute budget (#77). Empty when none are
	// configured.
	Budgets map[string]BudgetView `json:"budgets"`

	// Editable Always true in v1 — the policy is editable via PUT.
	Editable bool `json:"editable"`

	// Environments The environment catalog (#52); empty when none are configured.
	Environments *[]EnvironmentSpec `json:"environments,omitempty"`

	// Prices resource → $/unit-hour; `null` when no price sheet is configured.
	Prices *map[string]float64 `json:"prices,omitempty"`

	// Profiles The profile catalog (#7); empty when none are configured.
	Profiles *[]ProfileSpec `json:"profiles,omitempty"`

	// Quotas project → (resource → limit). Empty when no quotas are configured.
	Quotas map[string]map[string]float64 `json:"quotas"`

	// Source "file" (the untouched `--policy` boot seed) | "store" (edited via
	// PUT) | "none" (no policy configured at all).
	Source string `json:"source"`

	// Storage The storage catalog (#12); empty when none are configured.
	Storage *[]StorageEntry `json:"storage,omitempty"`
}

// PoolPurpose What a pool's capacity is for (#4). `compute` (the default when absent) admits interactive clusters and jobs; `serving` admits only RayService-backed services, so long-lived serving replicas never compete with notebooks for the same queue.
type PoolPurpose string

// PoolSpec A shared capacity pool: flavors + a cohort to borrow from (ADR-0010).
type PoolSpec struct {
	// Cohort Name of the Kueue cohort this pool's ClusterQueue joins for elastic
	// borrowing.
	Cohort string `json:"cohort"`

	// Elastic Whether workloads in this pool may be elastically resized (Kueue
	// elastic jobs / Workload Slices).
	Elastic bool `json:"elastic"`

	// FairSharingWeight Kueue `spec.fairSharing.weight` for the pool's ClusterQueue.
	FairSharingWeight float64      `json:"fair_sharing_weight"`
	Flavors           []FlavorSpec `json:"flavors"`
	GpuSharing        *GpuSharing  `json:"gpu_sharing,omitempty"`
	Name              string       `json:"name"`

	// Purpose What the pool's capacity is for (#4); absent = `compute`.
	Purpose *PoolPurpose `json:"purpose,omitempty"`
}

// PoolUsageView Live point-in-time usage of one pool (Slice 4): built from the pool's
// latest stored ClusterQueue/LocalQueue observation plus the spec's
// nominal quotas. NOT a timeseries — for history use `GET /api/v1/usage`.
// `projects` is the per-LocalQueue (per-project) attribution; empty when
// the observation predates per-LQ status or none exists.
type PoolUsageView struct {
	Pool string `json:"pool"`

	// Projects project → resource → allocated quantity.
	Projects map[string]map[string]float64 `json:"projects"`

	// SampledAt When the observation was recorded (unix seconds); `null` until the
	// pool reconcile loop has observed this pool.
	SampledAt   *int64                         `json:"sampled_at,omitempty"`
	Utilization map[string]ResourceUtilization `json:"utilization"`
}

// PoolView A pool as the control plane serves it: the stored spec metadata plus
// `total_nominal`, the per-resource sum of all flavors' nominal quotas.
type PoolView struct {
	Cohort            string       `json:"cohort"`
	CreatedAt         int64        `json:"created_at"`
	Elastic           bool         `json:"elastic"`
	FairSharingWeight float64      `json:"fair_sharing_weight"`
	Flavors           []FlavorSpec `json:"flavors"`

	// Generation Bumps when the spec changes (same convention as clusters).
	Generation int64       `json:"generation"`
	GpuSharing *GpuSharing `json:"gpu_sharing,omitempty"`
	Name       string      `json:"name"`

	// Purpose What the pool's capacity is for (#4); absent = `compute`.
	Purpose *PoolPurpose `json:"purpose,omitempty"`

	// TotalNominal Resource key → summed nominal quota across flavors, as a string.
	// A resource key whose quantity fails to parse on ANY flavor is
	// omitted entirely (a partial sum would misreport capacity); the
	// failure is logged. Display math only — the spec stays authoritative.
	TotalNominal map[string]string `json:"total_nominal"`
}

// ProfileSpec A named cluster shape in the profile catalog (#7): the head/worker shape and image a cluster or job gets when its spec names this profile. Expansion fills zero-valued shape fields and refuses conflicting non-empty ones (400).
type ProfileSpec struct {
	// Description Human-readable summary shown by clients.
	Description *string `json:"description,omitempty"`
	HeadCpu     string  `json:"head_cpu"`
	HeadMemory  string  `json:"head_memory"`

	// IdleTimeoutSecs Default inactivity reap window applied to clusters using this profile; `null` = none.
	IdleTimeoutSecs *int64 `json:"idle_timeout_secs,omitempty"`
	Image           string `json:"image"`

	// MaxWorkers Cap on total worker replicas for clusters using this profile; `null` = unlimited.
	MaxWorkers *int32 `json:"max_workers,omitempty"`

	// Name Catalog name a spec refers to (`ClusterSpec.profile`, `RayJobSpec.profile`).
	Name string `json:"name"`

	// Projects Projects that may use this profile; empty = every project.
	Projects   *[]string `json:"projects,omitempty"`
	RayVersion string    `json:"ray_version"`

	// Storage Storage catalog entries (#12) every cluster or job from this profile mounts, in addition to any the request names itself. Resolved against the project at create time like a request's own `storage`.
	Storage *[]string `json:"storage,omitempty"`

	// TtlSeconds Default absolute max-age cap applied to clusters using this profile; `null` = none.
	TtlSeconds   *int64        `json:"ttl_seconds,omitempty"`
	WorkerGroups []WorkerGroup `json:"worker_groups"`
}

